// AUTO-GENERATED by `ugly-app build:static` — do not edit.
// Regenerate with `ugly-app build:static` (also runs as part of `ugly-app build`).

export interface StaticAssetRecord {
  /** Full md5 of the file's bytes. */
  md5: string;
  /** R2 key — the public URL is this string with a leading slash. */
  key: string;
  bytes: number;
}

// `satisfies` (not `as const`) — it keeps the keys literal, which is what
// StaticAssetPath needs, while leaving the values mutable so the lookups below
// don't need a readonly-stripping cast.
export const staticAssets = {
  'probe/README.md': {
    md5: 'fa8d7db07e52c43e82de944cf8d9a5f9',
    key: 'static/probe/README.fa8d7db07e52.md',
    bytes: 193,
  },
  'probe/range-probe.bin': {
    md5: 'ce8e5c600a056f64d4107fea734c9fa0',
    key: 'static/probe/range-probe.ce8e5c600a05.bin',
    bytes: 262144,
  },
} satisfies Record<string, StaticAssetRecord>;

/** Every path present in `static/` at build time. */
export type StaticAssetPath = keyof typeof staticAssets;

/**
 * Origin the assets are served from — the R2 bucket's custom domain, which
 * Cloudflare's CDN edge-caches directly. Empty means same-origin.
 */
export const staticBaseUrl = 'https://static.ugly.chat';

/**
 * Dev serves the files off disk from the vite middleware at same-origin, so an
 * asset you just added works before it has ever been published. Prod uses the
 * CDN origin. `import.meta.env` only exists under vite; the try/catch keeps
 * this module importable from Node and Workers, where prod is the right answer.
 */
function origin(): string {
  try {
    if ((import.meta as { env?: { DEV?: boolean } }).env?.DEV) return '';
  } catch {
    // no import.meta.env — not a vite context.
  }
  return staticBaseUrl;
}

/**
 * Content-addressed URL for a static asset. A typo or a deleted-but-still
 * referenced asset is a tsc error here, not a 404 in production.
 */
export function staticUrl(p: StaticAssetPath): string {
  return (
    origin() + '/' + (staticAssets as Record<string, StaticAssetRecord>)[p]!.key
  );
}

/**
 * Escape hatch for runtime-computed names, e.g. `models/${name}.ugm`.
 * Returns null for an unknown path rather than building a URL that would 404.
 */
export function resolveStaticUrl(p: string): string | null {
  const rec = (staticAssets as Record<string, StaticAssetRecord>)[p];
  return rec ? origin() + '/' + rec.key : null;
}
